package ec.dmt.admin.school;
import jakarta.persistence.*;
@Entity @Table(name="student") public class Student { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="biometric_user_id",nullable=false,unique=true) private String biometricUserId; @Column(name="first_name",nullable=false) private String firstName; @Column(name="last_name",nullable=false) private String lastName; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="parallel_id",nullable=false) private SchoolParallel parallel; @Column(nullable=false) private boolean active=true; protected Student(){} public Student(String biometricUserId,String firstName,String lastName,SchoolParallel parallel,boolean active){this.biometricUserId=biometricUserId;this.firstName=firstName;this.lastName=lastName;this.parallel=parallel;this.active=active;} public Long getId(){return id;} public String getBiometricUserId(){return biometricUserId;} public String getFirstName(){return firstName;} public String getLastName(){return lastName;} public SchoolParallel getParallel(){return parallel;} public boolean isActive(){return active;} public void update(String biometricUserId,String firstName,String lastName,SchoolParallel parallel,boolean active){this.biometricUserId=biometricUserId;this.firstName=firstName;this.lastName=lastName;this.parallel=parallel;this.active=active;} }
